{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 동물보호 조례상 유기견 구조 시 주변 사람만 안전하면 동물이 다칠 위험이 큰 방법을 써도 되는지 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "주변 사람만 안전하면 동물이 다칠 위험이 큰 방법을 써도 되는 것은 아닙니다. 구청장 또는 동물보호센터의 장이 유기동물을 구조할 때에는 사람과 동물이 모두 안전한 방법을 사용하도록 조치하여야 합니다.",
          "b_ids": "동물보호:제10조제2항"
        }
      ],
      "e_status": "ANSWERED"
    },
    {
      "a_request": "R2",
      "b_asked": "서울특별시 동물보호 조례상 구청이나 동물보호센터가 유기견 구조와 관련해 지켜야 할 기준",
      "c_basis": "APPLIED",
      "d_claims": [
        {
          "a_text": "구청장과 동물보호센터의 장은 유기동물 또는 피학대동물을 발견하거나 발견신고를 받으면 지체 없이 구조·보호할 수 있도록 필요한 조치를 하여야 합니다. 구조할 때에는 사람과 동물이 모두 안전한 방법을 사용하도록 조치하여야 하며, 구조한 동물은 동물보호센터에 보호조치하여야 합니다.",
          "b_ids": "동물보호:제10조제1항, 동물보호:제10조제2항, 동물보호:제10조제3항"
        },
        {
          "a_text": "보호조치 중인 자는 공고기간 중 소유자가 반환을 요청하면 즉시 반환하여야 하고, 공고한 날부터 10일이 지나도 소유자가 나타나지 않으면 보호조치 중인 자에게 우선 입양 또는 기증할 수 있습니다. 구청장은 구조한 유기동물이 질병에 걸리거나 부상당한 경우 보호시설 보호조치 전에 공수의사에게 진료하게 할 수 있습니다.",
          "b_ids": "동물보호:제10조제4항, 동물보호:제13조제2항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
